-- ---- es ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ar-b2b-2015', 'es', 'Facturación electrónica obligatoria para responsables inscriptos en IVA (RG 3749/2015)', 'La Resolución General 3749/2015 de la AFIP hizo obligatoria la factura electrónica para los responsables inscriptos en el IVA y para los sujetos exentos, sobre la base del sistema voluntario que Argentina venía utilizando desde 2003. Cada comprobante se transmite a la AFIP (hoy ARCA) para su validación en tiempo real y recibe un CAE (Código de Autorización Electrónico) antes de poder entregarse al comprador -- un modelo de clearance, no de reporte posterior.', '["Tramitar el certificado digital ante AFIP/ARCA para solicitar la autorización de CAE", "Confirmar que el sistema de facturación o el portal ''Comprobantes en Línea'' genere XML conforme al esquema de AFIP"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ar-b2b-2019-universal', 'es', 'El régimen se vuelve universal -- se incorporan todos los monotributistas y las ventas a consumidor final (RG 4290/2018)', 'La RG 4290/2018 completó la implementación iniciada con los sujetos exentos el 1° de enero de 2019: a partir del 1° de abril de 2019, todos los monotributistas debieron reemplazar la factura en papel por factura electrónica o controlador fiscal -- incluidas las ventas a consumidores finales, con facturación por aplicación móvil obligatoria para las operaciones realizadas en el domicilio del cliente. Este es el punto en el que la factura electrónica se volvió efectivamente universal en toda la base de contribuyentes argentina, quedando solo las categorías más chicas del monotributo social con la opción manual.', '["Confirmar que la facturación de monotributistas y pequeños contribuyentes emita Factura B electrónica (consumidor final) y no en papel", "Habilitar la facturación por aplicación móvil para las ventas realizadas en el domicilio del cliente"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ar-format-2025', 'es', 'Se vuelven obligatorios los nuevos web services y el detalle de IVA/tipo de cambio (RG 5616/2024)', 'La RG 5616/2024 (Boletín Oficial del 18 de diciembre de 2024) actualizó las especificaciones técnicas de ARCA para la factura electrónica: desde el 15 de abril de 2025, los emisores deben utilizar los web services actualizados, el portal ''Comprobantes en Línea'' y la aplicación móvil en su versión revisada, y las facturas deben detallar el IVA por alícuota y el tipo de cambio utilizado en moneda extranjera. Es una actualización de formato y de información dentro del mismo modelo de clearance por CAE, no un cambio en el alcance de la obligación de facturar -- el mismo tratamiento que este sitio le da al Veri*Factu español.', '["Actualizar las integraciones de facturación a la especificación de web services de la RG 5616/2024 antes de depender del esquema anterior", "Confirmar que las facturas en moneda extranjera muestren el IVA detallado por alícuota y el tipo de cambio aplicado"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ar-sector-expansion-2026', 'es', 'Ampliación de sujetos obligados y liquidación electrónica mensual (RG 5824/2026)', 'La RG 5824/2026 (Boletín Oficial del 13 de febrero de 2026) amplió las categorías de contribuyentes obligados a emitir factura electrónica -- incorporando, entre otros, a entidades financieras, aseguradoras, administradoras de tarjetas de crédito, empresas de medicina prepaga e instituciones educativas -- y creó la ''liquidación electrónica mensual'', que permite a los emisores de alto volumen de esos sectores consolidar en un solo comprobante mensual por cliente en lugar de emitir uno por operación. Un nuevo umbral de $10.000.000 también exige identificar al consumidor final en las ventas de mayor importe, cerrando el vacío de la factura anónima para operaciones de alto valor. Vigente para las operaciones realizadas desde el 1° de julio de 2026.', '["Confirmar que los sectores recién incorporados (servicios financieros, seguros, medicina prepaga, educación) estén emitiendo factura electrónica", "Evaluar el comprobante de liquidación electrónica mensual para la facturación de clientes de alto volumen"]');

-- ---- de ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ar-b2b-2015', 'de', 'Pflicht zur elektronischen Rechnungsstellung für umsatzsteuerlich registrierte Steuerpflichtige (RG 3749/2015)', 'Mit der Allgemeinen Entschließung 3749/2015 machte die AFIP die elektronische Rechnungsstellung für umsatzsteuerlich registrierte und von der Umsatzsteuer befreite Steuerpflichtige verbindlich -- aufbauend auf dem seit 2003 freiwilligen System. Jede Rechnung wird der AFIP (heute ARCA) zur Echtzeitprüfung übermittelt und erhält einen CAE (Código de Autorización Electrónico), bevor sie an den Käufer ausgeliefert werden darf -- ein Clearing-Modell, kein nachträgliches Meldeverfahren.', '["Digitales Steuerzertifikat bei AFIP/ARCA beantragen, um die CAE-Autorisierung zu erhalten", "Sicherstellen, dass die Rechnungssoftware oder das Portal ''Comprobantes en Línea'' XML gemäß dem AFIP-Schema erzeugt"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ar-b2b-2019-universal', 'de', 'Die Pflicht wird umfassend -- alle Monotributistas und Verkäufe an Endverbraucher werden einbezogen (RG 4290/2018)', 'Die RG 4290/2018 vollendete die am 1. Januar 2019 mit den umsatzsteuerbefreiten Steuerpflichtigen begonnene Umstellung: Ab dem 1. April 2019 mussten alle Monotributistas (Argentiniens vereinfachte Kleinunternehmerregelung) Papierrechnungen durch elektronische Rechnungen oder einen Fiskalcontroller ersetzen -- einschließlich Verkäufen an Endverbraucher, wobei für Geschäfte am Kundenstandort eine Rechnungsstellung per Mobil-App vorgeschrieben wurde. Damit wurde die elektronische Rechnungsstellung faktisch für die gesamte argentinische Steuerpflichtigenbasis verbindlich; nur die kleinsten Kategorien des Sozial-Monotributo behielten die manuelle Option.', '["Sicherstellen, dass Monotributistas und Kleinunternehmen elektronische Rechnungen des Typs B (Endverbraucher) statt Papierrechnungen ausstellen", "Mobile Rechnungsstellung für Geschäfte am Kundenstandort aktivieren"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ar-format-2025', 'de', 'Aktualisierte Web-Services und detaillierte USt-/Wechselkursangaben werden verbindlich (RG 5616/2024)', 'Die RG 5616/2024 (Amtsblatt vom 18. Dezember 2024) aktualisierte die technischen Vorgaben der ARCA für die elektronische Rechnungsstellung: Ab dem 15. April 2025 müssen Aussteller die überarbeiteten Web-Services, das Portal ''Comprobantes en Línea'' und die aktualisierte Mobil-App verwenden, und Rechnungen müssen die Umsatzsteuer nach Steuersatz aufgeschlüsselt sowie den verwendeten Fremdwährungskurs ausweisen. Es handelt sich um eine Format- und Angabenaktualisierung innerhalb desselben CAE-Clearing-Modells, nicht um eine Änderung des Pflichtumfangs -- dieselbe Einordnung, die diese Seite dem spanischen VeriFactu gibt.', '["Rechnungsintegrationen auf die Web-Service-Spezifikation der RG 5616/2024 aktualisieren, bevor man sich auf das ältere Schema verlässt", "Sicherstellen, dass Rechnungen in Fremdwährung die USt. nach Steuersatz aufgeschlüsselt und den angewandten Wechselkurs anzeigen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ar-sector-expansion-2026', 'de', 'Ausweitung auf weitere Sektoren und monatliche Sammelabrechnung (RG 5824/2026)', 'Die RG 5824/2026 (Amtsblatt vom 13. Februar 2026) erweiterte die Kategorien der zur elektronischen Rechnungsstellung verpflichteten Steuerpflichtigen -- unter anderem Finanzinstitute, Versicherer, Kreditkartenverwalter, private Krankenversicherungen und Bildungseinrichtungen -- und führte die ''liquidación electrónica mensual'' ein, mit der Aussteller mit hohem Volumen in diesen Sektoren die Transaktionen eines Kunden in einer monatlichen Sammelrechnung statt einzeln abrechnen können. Ein neuer Schwellenwert von ARS 10.000.000 verlangt zudem bei größeren Verkäufen die Identifizierung des Endverbrauchers und schließt damit die Lücke anonymer Rechnungen bei hochwertigen Transaktionen. Gültig für Geschäfte ab dem 1. Juli 2026.', '["Sicherstellen, dass neu einbezogene Sektoren (Finanzdienstleistungen, Versicherungen, private Krankenversicherung, Bildung) auf elektronische Rechnungsstellung umgestellt haben", "Die monatliche Sammelabrechnung für die Rechnungsstellung volumenstarker Kunden prüfen"]');

-- ---- fr ----
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ar-b2b-2015', 'fr', 'Facturation électronique obligatoire pour les assujettis inscrits à la TVA (RG 3749/2015)', 'La Résolution générale 3749/2015 de l''AFIP a rendu la facturation électronique obligatoire pour les assujettis inscrits à la TVA et pour les sujets exonérés, en s''appuyant sur le système volontaire en vigueur en Argentine depuis 2003. Chaque facture est transmise à l''AFIP (aujourd''hui ARCA) pour validation en temps réel et reçoit un CAE (Código de Autorización Electrónico) avant de pouvoir être remise à l''acheteur -- un modèle de clearance, et non un reporting a posteriori.', '["Obtenir un certificat fiscal numérique auprès de l''AFIP/ARCA pour demander l''autorisation CAE", "Vérifier que le logiciel de facturation ou le portail ''Comprobantes en Línea'' génère du XML conforme au schéma de l''AFIP"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ar-b2b-2019-universal', 'fr', 'Le régime devient universel -- tous les monotributistas et les ventes aux consommateurs finaux sont inclus (RG 4290/2018)', 'La RG 4290/2018 a achevé la mise en œuvre entamée le 1er janvier 2019 avec les sujets exonérés de TVA : à partir du 1er avril 2019, chaque monotributista (le régime simplifié argentin pour les petits contribuables) a dû remplacer la facturation papier par une facture électronique ou un contrôleur fiscal -- y compris pour les ventes aux consommateurs finaux, avec une facturation par application mobile obligatoire pour les opérations réalisées chez le client. C''est le moment où la facturation électronique est devenue de fait universelle pour l''ensemble des contribuables argentins, seules les catégories les plus modestes du monotributo social conservant l''option manuelle.', '["Vérifier que la facturation des monotributistas et des petites entreprises émet des factures électroniques de type B (consommateur final) et non papier", "Activer la facturation par application mobile pour les ventes réalisées chez le client"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ar-format-2025', 'fr', 'Les nouveaux services web et le détail TVA/taux de change deviennent obligatoires (RG 5616/2024)', 'La RG 5616/2024 (Journal officiel du 18 décembre 2024) a mis à jour les spécifications techniques de l''ARCA pour la facturation électronique : à partir du 15 avril 2025, les émetteurs doivent utiliser les services web actualisés, le portail ''Comprobantes en Línea'' et l''application mobile dans leur version révisée, et les factures doivent détailler la TVA par taux et indiquer le taux de change utilisé en devise étrangère. Il s''agit d''une mise à jour de format et d''information au sein du même modèle de clearance par CAE, non d''un changement du périmètre de l''obligation -- le même traitement que ce site applique au VeriFactu espagnol.', '["Mettre à jour les intégrations de facturation vers la spécification de services web de la RG 5616/2024 avant de s''appuyer sur l''ancien schéma", "Vérifier que les factures en devise étrangère détaillent la TVA par taux et indiquent le taux de change appliqué"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('ar-sector-expansion-2026', 'fr', 'Extension à de nouveaux secteurs et facturation mensuelle consolidée (RG 5824/2026)', 'La RG 5824/2026 (Journal officiel du 13 février 2026) a élargi les catégories de contribuables tenus d''émettre des factures électroniques -- incluant, entre autres, les établissements financiers, les assureurs, les gestionnaires de cartes de crédit, les organismes de santé prépayée et les établissements d''enseignement -- et a introduit la ''liquidación electrónica mensual'', permettant aux émetteurs à fort volume de ces secteurs de regrouper les opérations d''un client en une seule facture électronique mensuelle plutôt que d''en émettre une par transaction. Un nouveau seuil de 10 000 000 ARS impose également l''identification du consommateur final pour les ventes de montant plus élevé, comblant ainsi la faille des factures anonymes pour les transactions à forte valeur. En vigueur pour les opérations réalisées à compter du 1er juillet 2026.', '["Vérifier que les secteurs nouvellement concernés (services financiers, assurance, santé prépayée, éducation) ont adopté la facturation électronique", "Évaluer le bon de liquidation mensuelle consolidée pour la facturation des clients à fort volume"]');
